// src/HomePage.js
import React from 'react';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Box,
  Container,
  Card,
  CardContent,
  CardMedia,
  Grid,
} from '@mui/material';
import SportsSoccerIcon from '@mui/icons-material/SportsSoccer';

const HomePage = () => {
  return (
    <>
      {/* Navigation */}
      <AppBar position="static">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            Turf Booking
          </Typography>
          <Button color="inherit">Home</Button>
          <Button color="inherit">About</Button>
          <Button color="inherit">Book Now</Button>
          <Button color="inherit">Contact</Button>
        </Toolbar>
      </AppBar>

      {/* Hero Section */}
      <Box
        sx={{
          backgroundImage: `url(https://source.unsplash.com/1600x900/?soccer)`,
          height: '60vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: '#fff',
          textAlign: 'center',
        }}
      >
        <Box>
          <Typography variant="h2" gutterBottom>
            Book Your Turf
          </Typography>
          <Typography variant="h5" paragraph>
            Find the perfect turf for your game today!
          </Typography>
          <Button
            variant="contained"
            color="primary"
            size="large"
            startIcon={<SportsSoccerIcon />}
          >
            Book Now
          </Button>
        </Box>
      </Box>

      {/* Available Turfs Section */}
      <Container sx={{ my: 4 }}>
        <Typography variant="h4" gutterBottom align="center">
          Available Turfs
        </Typography>
        <Grid container spacing={4}>
          {[1, 2, 3].map((turf) => (
            <Grid item xs={12} sm={6} md={4} key={turf}>
              <Card>
                <CardMedia
                  component="img"
                  height="140"
                  image={``}
                  alt="Turf"
                />
                <CardContent>
                  <Typography variant="h5" gutterBottom>
                    Turf {turf}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    This is a great turf for soccer. Book your slot now to
                    ensure you have the best spot for your match.
                  </Typography>
                  <Button variant="outlined" color="primary" sx={{ mt: 2 }}>
                    Book Now
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>

      {/* Footer */}
      <Box sx={{ py: 4, textAlign: 'center', backgroundColor: '#f5f5f5' }}>
        <Typography variant="body1">
          © {new Date().getFullYear()} Turf Booking. All rights reserved.
        </Typography>
      </Box>
    </>
  );
};

export default HomePage;
